<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{ActivityLog,Media,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Hash,Storage};
class ManagementController extends Controller {
 public function users(){return view('admin.users',['items'=>User::latest()->paginate(25)]);} public function saveUser(Request $r,?User $user=null){$data=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users,email,'.($user?->id??'NULL'),'role'=>'required|in:super_admin,editor','password'=>($user?'nullable':'required').'|min:10']);if(empty($data['password']))unset($data['password']);else $data['password']=Hash::make($data['password']);($user?:new User)->fill($data)->save();return back()->with('success','User saved.');} public function deleteUser(User $user){abort_if($user->id===auth()->id(),422,'You cannot delete your own account.');$user->delete();return back()->with('success','User deleted.');}
 public function media(){return view('admin.media',['items'=>Media::latest()->paginate(30)]);} public function upload(Request $r){$r->validate(['files'=>'required','files.*'=>'file|mimes:jpg,jpeg,png,webp,gif,mp3,pdf|max:51200','alt_text'=>'nullable|max:255']);foreach($r->file('files') as $file){$path=$file->store('media','public');Media::create(['name'=>$file->getClientOriginalName(),'file_path'=>$path,'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'alt_text'=>$r->alt_text,'uploaded_by'=>auth()->id()]);}return back()->with('success','Media uploaded.');} public function deleteMedia(Media $media){Storage::disk('public')->delete($media->file_path);$media->delete();return back()->with('success','Media deleted.');}
 public function logs(){return view('admin.logs',['items'=>ActivityLog::with('user')->latest()->paginate(50)]);}
}
